param([string]$EvidenceDirectory = (Join-Path $env:TEMP ('forwarder-fwd07-browser-' + [guid]::NewGuid().ToString('N'))))
$ErrorActionPreference='Stop'; $repo=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path; $password=[guid]::NewGuid().ToString('N'); $apiPort=5057; $uiPort=8087
foreach($port in @($apiPort,$uiPort)){ $probe=[System.Net.Sockets.TcpListener]::new([System.Net.IPAddress]::Loopback,$port); try{$probe.Start()}finally{$probe.Stop()} }
$env:APP_ENV='test';$env:FWD07_UAT_PASSWORD=$password;$env:FWD07_UAT_API_PORT="$apiPort";$env:FWD07_UAT_BASE_URL="http://127.0.0.1:$uiPort";$env:FWD07_UAT_EVIDENCE_DIR=$EvidenceDirectory;$env:VITE_BACKEND_URL="http://127.0.0.1:$apiPort";New-Item -ItemType Directory -Force $EvidenceDirectory|Out-Null
$backend=Start-Process python -ArgumentList '-m','scripts.uat.fwd07_browser_fixture' -WorkingDirectory $repo -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $EvidenceDirectory 'backend.out') -RedirectStandardError (Join-Path $EvidenceDirectory 'backend.err');$frontend=$null
try {for($i=0;$i -lt 60;$i++){try{if((Invoke-WebRequest -UseBasicParsing "http://127.0.0.1:$apiPort/api/health" -TimeoutSec 1).StatusCode -eq 200){break}}catch{};Start-Sleep -Milliseconds 250};if($backend.HasExited){throw 'FWD07 backend failed'};$frontend=Start-Process node -ArgumentList 'node_modules/vite/bin/vite.js','--host','127.0.0.1','--port',"$uiPort",'--strictPort' -WorkingDirectory $repo -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $EvidenceDirectory 'frontend.out') -RedirectStandardError (Join-Path $EvidenceDirectory 'frontend.err');Start-Sleep -Seconds 2;node (Join-Path $PSScriptRoot 'fwd07_browser_runner.mjs');if($LASTEXITCODE -ne 0){throw 'FWD07 browser failed'};Write-Output "FWD07_BROWSER_EVIDENCE=$EvidenceDirectory"} finally {if($frontend -and -not $frontend.HasExited){Stop-Process $frontend -Force};if($backend -and -not $backend.HasExited){Stop-Process $backend -Force}}
